css:
:scope { position: relative; overflow: hidden; }
.th { position: relative; text-align: center; }
.th__glow { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse 50% 38% at 50% 74%, color-mix(in oklab, var(--os-color-accent) 40%, transparent), transparent 72%); }
.th__geo { position: absolute; left: 50%; top: 52%; width: min(1100px, 150vw); height: auto; transform: translate(-50%, 0); pointer-events: none; opacity: .32; }
.th__geo-lines { fill: none; stroke: var(--os-color-accent); stroke-width: .35; }
.th__dots { stroke-dasharray: .6 2.4; }
.th__copy { position: relative; max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; align-items: center; gap: var(--os-space-md); }
.th__lotus { width: 120px; height: 40px; fill: none; stroke: var(--os-color-accent); stroke-width: 1.2; stroke-linejoin: round; }
.th__eyebrow { margin: 0; font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: var(--os-type-eyebrow-text-transform); color: var(--os-eyebrow-color); }
.th__title { margin: 0; font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-display-font-size); line-height: var(--os-type-display-line-height); color: var(--os-color-heading); text-wrap: balance; background: linear-gradient(100deg, color-mix(in oklab, var(--os-color-accent) 85%, black) 0%, var(--os-color-heading) 40%, var(--os-color-accent) 62%, color-mix(in oklab, var(--os-color-accent) 70%, black) 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.th__tagline { margin: 0; font-family: var(--os-font-heading); font-style: italic; font-size: var(--os-type-h2-font-size); line-height: 1.15; color: var(--os-color-heading); opacity: .85; }
.th__intro { max-width: 36em; font-size: var(--os-type-lead-font-size); line-height: var(--os-type-lead-line-height); color: var(--os-color-text); }
.th__actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--os-space-md); margin-top: var(--os-space-sm); }
.th__btn { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0 32px; border-radius: 999px; text-decoration: none; font-family: var(--os-font-label); font-size: var(--os-type-button-font-size, 15px); letter-spacing: var(--os-type-button-letter-spacing, .14em); text-transform: uppercase; }
.th__btn--gold { background: linear-gradient(100deg, var(--os-color-accent), var(--os-color-heading) 50%, var(--os-color-accent)); color: var(--os-color-accent-text); box-shadow: 0 0 40px color-mix(in oklab, var(--os-color-accent) 35%, transparent); }
.th__btn--line { border: 1px solid var(--os-color-heading); color: var(--os-color-heading); }
.th__btn:hover { opacity: .9; }
.th__portal { position: relative; max-width: 480px; margin: var(--os-space-2xl) auto 0; padding: 14px 14px 0; }
.th__portal::before { content: ""; position: absolute; inset: 0; border: 1px solid var(--os-color-accent); border-bottom: 0; border-radius: 320px 320px 0 0; opacity: .85; }
.th__portal::after { content: ""; position: absolute; inset: -14px -14px 0; border: 1px solid var(--os-color-accent); border-bottom: 0; border-radius: 340px 340px 0 0; opacity: .4; }
.th__arch { position: relative; overflow: hidden; border-radius: 300px 300px 0 0; box-shadow: 0 0 110px color-mix(in oklab, var(--os-color-accent) 45%, transparent); }
.th__arch picture, .th__arch img { display: block; width: 100%; aspect-ratio: 5 / 6; object-fit: cover; }
.th__steps { position: relative; display: flex; flex-direction: column; align-items: center; gap: 6px; }
.th__steps span { display: block; height: 12px; background: linear-gradient(90deg, transparent, var(--os-color-accent) 20%, var(--os-color-heading) 50%, var(--os-color-accent) 80%, transparent); }
.th__steps span:nth-child(1) { width: min(600px, 92%); }
.th__steps span:nth-child(2) { width: min(740px, 96%); opacity: .7; }
.th__steps span:nth-child(3) { width: min(900px, 100%); opacity: .45; }
.th__copy > * { animation: th-rise 900ms ease both; }
.th__copy > :nth-child(2) { animation-delay: 90ms; }
.th__copy > :nth-child(3) { animation-delay: 180ms; }
.th__geo { animation: th-turn 240s linear infinite; }
@keyframes th-rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@keyframes th-turn { from { transform: translate(-50%, 0) rotate(0deg); } to { transform: translate(-50%, 0) rotate(360deg); } }
@media (max-width: 767px) { .th__portal { max-width: 86%; margin-top: var(--os-space-xl); } .th__btn { width: 100%; } .th__actions { width: 100%; flex-direction: column; } .th__geo { top: 58%; } }
@media (prefers-reduced-motion: reduce) { .th__copy > *, .th__geo { animation: none; } }
